arguments.command:
for b in rachel monica phoebe joey chandler ross; do
  echo "=== $b ===";
  git -C /tmp/ross-main-wt fetch origin friend/$b >/dev/null 2>&1;
  git rev-list --count origin/friend/$b;
  git log origin/friend/$b --format='%H' | while read sha; do git show -s --format='%B' $sha | grep -q '^Friend-Message: 1' && echo $sha; done | wc -l;
done

for b in rachel monica phoebe joey chandler ross; do git -C /tmp/ross-main-wt fetch origin friend/$b >/dev/null 2>&1; done
for b in rachel monica phoebe joey chandler; do
  echo "=== $b latest ===";
  git log origin/friend/$b -1 --format='%ci %s';
done
